CREATE TABLE auth_user (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE auth_session (id text PRIMARY KEY, token text NOT NULL UNIQUE, expires_at timestamp NOT NULL, created_at timestamp NOT NULL, updated_at timestamp NOT NULL, ip_address text, user_agent text, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE);
CREATE INDEX auth_session_user ON auth_session(user_id);
CREATE TABLE auth_account (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamp, refresh_token_expires_at timestamp, scope text, password text, created_at timestamp NOT NULL, updated_at timestamp NOT NULL, UNIQUE(provider_id, account_id));
CREATE TABLE auth_verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamp NOT NULL, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE event_series (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE event_edition (id text PRIMARY KEY, series_id text NOT NULL REFERENCES event_series(id), name text NOT NULL, venue text NOT NULL, location text NOT NULL, timezone text NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL CHECK(ends_on >= starts_on), origin text NOT NULL CHECK(origin IN ('fictional_demo', 'operated', 'historical_import')), published boolean NOT NULL DEFAULT false);
CREATE TABLE division (id text PRIMARY KEY, event_id text NOT NULL REFERENCES event_edition(id), name text NOT NULL, discipline text NOT NULL CHECK(discipline IN ('men_four', 'women_four', 'mixed_doubles')), format text NOT NULL);
CREATE TABLE draw_session (id text PRIMARY KEY, division_id text NOT NULL REFERENCES division(id), number integer NOT NULL CHECK(number > 0), starts_at timestamptz NOT NULL, state text NOT NULL CHECK(state IN ('scheduled','live','completed')), UNIQUE(division_id,number));
CREATE TABLE event_entry (id text PRIMARY KEY, division_id text NOT NULL REFERENCES division(id), display_name text NOT NULL);
CREATE TABLE game (id text PRIMARY KEY, draw_id text NOT NULL REFERENCES draw_session(id), sheet text NOT NULL, phase text NOT NULL, state text NOT NULL CHECK(state IN ('scheduled','live','confirmed')), entry_a text REFERENCES event_entry(id), entry_b text REFERENCES event_entry(id), slot_a text NOT NULL, slot_b text NOT NULL, total_a integer CHECK(total_a >= 0), total_b integer CHECK(total_b >= 0), hammer text CHECK(hammer IN ('a','b')), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(state <> 'scheduled' OR (total_a IS NULL AND total_b IS NULL)));
CREATE TABLE game_end_score (game_id text NOT NULL REFERENCES game(id) ON DELETE CASCADE, side text NOT NULL CHECK(side IN ('a','b')), end_number integer NOT NULL CHECK(end_number BETWEEN 1 AND 20), state text NOT NULL CHECK(state IN ('played','unknown','upcoming','unplayed')), points integer, PRIMARY KEY(game_id,side,end_number), CHECK((state = 'played' AND points >= 0 AND points <= 8) OR (state <> 'played' AND points IS NULL)));
CREATE TABLE role_grant (id text PRIMARY KEY, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('administrator','organizer','scorekeeper','reviewer')), event_id text REFERENCES event_edition(id), game_id text REFERENCES game(id), CHECK((role='administrator' AND event_id IS NULL AND game_id IS NULL) OR (role IN ('organizer','reviewer') AND event_id IS NOT NULL AND game_id IS NULL) OR (role='scorekeeper' AND event_id IS NOT NULL AND game_id IS NOT NULL)));
CREATE INDEX role_grant_user ON role_grant(user_id);
CREATE TABLE audit_record (id text PRIMARY KEY, actor_id text NOT NULL REFERENCES auth_user(id), action text NOT NULL, resource_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE worker_probe (id text PRIMARY KEY, completed_at timestamptz NOT NULL DEFAULT now());
